const b = $('Webhook').first().json.body || {};
const token = $input.first().json.telegram_bot_token;
const esc = s => String(s || '').replace(/\\/g, '\\\\').replace(/,/g, '\\,').replace(/;/g, '\\;').replace(/\r?\n/g, '\\n');
let tel = String(b.telephone || '').replace(/[^0-9+]/g, '');
if (tel.startsWith('0') && tel.length === 10) tel = '+33' + tel.slice(1);
const prenom = b.prenom || '';
const nom = String(b.nom || '').toUpperCase();
const complet = (prenom + ' ' + nom).trim();
const lignes = ['BEGIN:VCARD', 'VERSION:3.0',
  'N:' + esc(nom) + ';' + esc(prenom) + ';;;',
  'FN:' + esc(complet)];
if (b.societe) lignes.push('ORG:' + esc(b.societe));
if (tel) lignes.push('TEL;TYPE=CELL:' + tel);
if (b.email) lignes.push('EMAIL;TYPE=INTERNET:' + b.email);
if (b.adresse || b.ville) lignes.push('ADR;TYPE=HOME:;;' + esc(b.adresse) + ';' + esc(b.ville) + ';;' + esc(b.code_postal) + ';France');
if (b.note) lignes.push('NOTE:' + esc(b.note));
lignes.push('END:VCARD');
const vcf = lignes.join('\r\n') + '\r\n';
return [{
  json: { url: 'https://api.telegram.org/bot' + token + '/sendDocument', chat_id: '1857340429', caption: complet + ' : tape sur le fichier, Partager, puis Contacts' },
  binary: { data: { data: Buffer.from(vcf, 'utf8').toString('base64'), mimeType: 'text/vcard', fileName: (complet || 'contact').replace(/[^A-Za-z0-9 _-]/g, '') + '.vcf' } }
}];
